# Identify rectangular vs scattered cells

from collections import defaultdict
import numpy as np

# Find all non-9 cells
non_bg = defaultdict(list)
for r in range(19):
    for c in range(12):
        if grid[r][c] != 9:
            non_bg[grid[r][c]].append((r,c))

def get_minimal_rect(points):
    if not points:
        return None
    rows = [p[0] for p in points]
    cols = [p[1] for p in points]
    min_r, max_r = min(rows), max(rows)
    min_c, max_c = min(cols), max(cols)
    rect_count = (max_r - min_r + 1) * (max_c - min_c + 1)
    return rect_count, set((r, c) for r in range(min_r, max_r+1) for c in range(min_c, max_c+1))

for color, cells in non_bg.items():
    rect_count, rect_set = get_minimal_rect(cells)
    cell_set = set(cells)

    if rect_count == len(cells):
